import { pascal, modelNodes, compactValidation } from "./normalize.mjs";
// Go rejects a literal BOM even inside strings; emit it as an escape.
const q = (value) => JSON.stringify(value).replaceAll("\uFEFF", "\\ufeff");
export function emitGo(ir) {
  const { nodes, methods, behavior: b } = ir;
  const validation = compactValidation(ir);
  const out = [
    "// Code generated by native/codegen/generate.mjs; DO NOT EDIT.",
    "package octo",
    'import ("context"; "encoding/json")'
  ];
  function typ(id, definition = false) {
    const n = nodes[id],
      s = n.schema;
    if (n.ref !== undefined) return nodes[n.ref].name;
    if (!definition && (s.properties || s.oneOf || s.anyOf)) return n.name;
    if (s.oneOf || s.anyOf) return "json.RawMessage";
    if (s.type === "object" || s.properties) return "map[string]json.RawMessage";
    if (s.type === "array") return "[]" + typ(n.branches.items);
    if (Array.isArray(s.type)) {
      const t = s.type.filter((t) => t !== "null");
      return t.length === 1
        ? "*" +
            ({ string: "string", integer: "int64", number: "json.Number", boolean: "bool" }[t[0]] ??
              "json.RawMessage")
        : "json.RawMessage";
    }
    const t =
      s.type ??
      (s.const !== undefined ? typeof s.const : s.enum?.length ? typeof s.enum[0] : undefined);
    return (
      { string: "string", integer: "int64", number: "json.Number", boolean: "bool" }[t] ??
      "json.RawMessage"
    );
  }
  for (const n of modelNodes(ir)) {
    const s = n.schema;
    if (s.properties) {
      out.push(`type ${n.name} struct {`);
      for (const [k, id] of Object.entries(n.properties)) {
        const required = s.required?.includes(k);
        out.push(
          `${pascal(k)} ${required ? typ(id) : `Optional[${typ(id)}]`} \`json:${q(k + (required ? "" : ",omitzero"))}\``
        );
      }
      if (s.additionalProperties !== false) out.push('Extra map[string]json.RawMessage `json:"-"`');
      out.push("}");
      if (s.additionalProperties !== false) {
        out.push(
          `func (v ${n.name}) MarshalJSON() ([]byte,error) {type plain ${n.name}; return marshalOpen(plain(v), v.Extra)}`,
          `func (v *${n.name}) UnmarshalJSON(data []byte) error {type plain ${n.name}; var p plain; if err:=unmarshalOpen(data,&p,&p.Extra);err!=nil{return err};*v=${n.name}(p);return nil}`
        );
      }
    } else {
      out.push(`type ${n.name} = ${typ(n.id, true)}`);
    }
  }
  // Validate public inputs before typed binding; opaque numbers remain RawMessage.
  out.push(
    "var definitionRules = map[string]int{" +
      Object.entries(validation.roots)
        .map(([n, id]) => `${q(n)}:${id}`)
        .join(",") +
      "}"
  );
  out.push("var rules = []rule{");
  for (const n of validation.nodes) {
    const s = n.schema,
      fields = [];
    const put = (k, v) => fields.push(`${k}:${v}`);
    if (n.ref !== undefined) put("Ref", n.ref + 1);
    if (s.type)
      put(
        "Types",
        "[]string{" + (Array.isArray(s.type) ? s.type : [s.type]).map(q).join(",") + "}"
      );
    if (s.const !== undefined) put("Values", `[]string{${q(JSON.stringify(s.const))}}`);
    else if (s.enum)
      put("Values", "[]string{" + s.enum.map((v) => q(JSON.stringify(v))).join(",") + "}");
    if (s.required) put("Required", "[]string{" + s.required.map(q).join(",") + "}");
    if (s.properties)
      put(
        "Properties",
        "map[string]int{" +
          Object.entries(n.properties)
            .map(([k, v]) => `${q(k)}:${v}`)
            .join(",") +
          "}"
      );
    if (s.additionalProperties === false) put("Strict", "true");
    for (const [k, v] of Object.entries(n.branches))
      put(pascal(k), Array.isArray(v) ? "[]int{" + v.join(",") + "}" : v + 1);
    for (const k of [
      "minimum",
      "maximum",
      "minLength",
      "maxLength",
      "minItems",
      "maxItems",
      "minProperties",
      "maxProperties"
    ])
      if (s[k] !== undefined) put(pascal(k), `bound(${s[k]})`);
    for (const k of ["pattern", "format"]) if (s[k]) put(pascal(k), q(s[k]));
    if (s.uniqueItems) put("UniqueItems", "true");
    const ext = Object.keys(s).filter((k) => k.startsWith("x-"));
    if (ext.length)
      put(
        "Extensions",
        "map[string]int{" + ext.map((k) => `${q(k)}:${s[k] === true ? 1 : s[k]}`).join(",") + "}"
      );
    out.push("{" + fields.join(",") + "},");
  }
  out.push("}");
  out.push(
    "var methodRules = map[string]methodRule{" +
      validation.methods
        .map(
          (m) =>
            `${q(m.method)}:{Params:${m.paramsId},Result:${m.resultId},SideEffect:${m.sideEffect},Stream:${m.stream}}`
        )
        .join(",") +
      "}"
  );
  for (const [k, v] of Object.entries(b.limits)) out.push(`const limit${pascal(k)} = ${v}`);
  for (const [k, v] of Object.entries(b.timeoutsMs)) out.push(`const timeout${pascal(k)} = ${v}`);
  for (const [k, v] of Object.entries(b))
    if (Array.isArray(v))
      out.push(
        `var ${k} = []${typeof v[0] === "number" ? "int" : "string"}{${v.map((x) => (typeof x === "string" ? q(x) : x)).join(",")}}`
      );
  out.push(
    "var identityInputFields = map[string]string{" +
      Object.entries(b.identityInputFields)
        .map(([k, v]) => `${q(k)}:${q(v)}`)
        .join(",") +
      "}"
  );
  // Generate an RPC wrapper for each method so schema additions reach the SDK automatically.
  for (const m of methods) {
    if (m.stream) continue;
    out.push(
      `func (c *Client) RPC${m.name}(ctx context.Context, params ${nodes[m.paramsId].name}) (${nodes[m.resultId].name}, error) { var result ${nodes[m.resultId].name}; err:=c.rpc(ctx, ${q(m.method)}, params, &result, nil); return result,err }`
    );
  }
  return {
    "native/go/octo_runtime_generated.go": out.join("\n") + "\n"
  };
}
